export async function handler(event) {
  const cosechaId = Number(event.pathParameters.cosechaId);
  const { granjaId } = JSON.parse(event.body);
  const resultado = await trasladarCosechaService(cosechaId, granjaId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarCosechaRepository } from './repository.mjs';
import { buscarGranjaRepository } from '../../granjas/consultar/repository.mjs';

export async function trasladarCosechaService(cosechaId, granjaId) {
  const granja = await buscarGranjaRepository(granjaId);
  if (!granja) throw new Error('Granja no encontrado');
  return trasladarCosechaRepository(cosechaId, granjaId);
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_COSECHA, MODELO_GRANJA } from '../../models/granja-cosecha.model.mjs';

export async function trasladarCosechaRepository(cosechaId, granjaId) {
  const { Attributes } = await MODELO_COSECHA.build(EntityRepository).update(
    { cosechaId, granjaId },
    {
      condition: { attr: 'cosechaId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarGranjaService } from './service.mjs';

export async function handler(event) {
  const granjaId = Number(event.pathParameters.granjaId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarGranjaService(granjaId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarGranjaRepository, consultarGranjaRepository } from './repository.mjs';

export async function consultarGranjaService(granjaId, minimo) {
  const granja = await buscarGranjaRepository(granjaId);
  if (!granja) throw new Error('Granja no encontrado');
  const cosechas = await consultarGranjaRepository(granjaId, minimo);
  return { granja, cosechas };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_COSECHA, MODELO_GRANJA } from '../../models/granja-cosecha.model.mjs';

export async function buscarGranjaRepository(granjaId) {
  const { Item } = await MODELO_GRANJA.build(EntityRepository).get(
    { granjaId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarGranjaRepository(granjaId, minimo) {
  const { Items = [] } = await MODELO_COSECHA.build(EntityRepository).query(
    { index: 'PorGranja', partition: granjaId },
    { filters: { Cosecha: { attr: 'kilos', gte: minimo } } }
  );
  return Items;
}
